-- AlterTable
ALTER TABLE "EquipmentUnit" ADD COLUMN     "lastCheckedAt" TIMESTAMP(3),
ADD COLUMN     "location" TEXT,
ADD COLUMN     "notes" TEXT,
ADD COLUMN     "purchasedAt" TIMESTAMP(3),
ADD COLUMN     "serialIsPlaceholder" BOOLEAN NOT NULL DEFAULT false;


-- Data backfill (hand-written): mark serials auto-generated by the app (pattern
-- PREFIX-XXXX-n, e.g. MIRCRO-A415-1) as placeholders so they are not mistaken for real
-- manufacturer serials. Seed values such as FRANKA-0001 cannot be distinguished and stay as-is.
UPDATE "EquipmentUnit" SET "serialIsPlaceholder" = true
WHERE "serialNumber" ~ '^[A-Z0-9]{1,6}-[0-9A-F]{4}-[0-9]+$';
